def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = []
    op = []
    cc = cd = dc = dd = 0
    for a, b in history:
        me.append(a)
        op.append(b)
        if a == 'C':
            if b == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if b == 'C':
                dc += 1
            else:
                dd += 1

    opp_c = cc + dc
    opp_d = cd + dd
    my_c = cc + cd
    my_d = dc + dd
    score_units = dc - cd

    w = 10 if n >= 10 else n
    start = n - w
    rec_op_c = 0
    rec_op_d = 0
    for i in range(start, n):
        if op[i] == 'C':
            rec_op_c += 1
        else:
            rec_op_d += 1

    w20 = 20 if n >= 20 else n
    start20 = n - w20
    rec20_op_c = 0
    for i in range(start20, n):
        if op[i] == 'C':
            rec20_op_c += 1
    recent_coop20 = rec20_op_c * 5 >= w20 * 4

    last_me = me[-1]
    last_op = op[-1]

    opp_run = 1
    for i in range(n - 2, -1, -1):
        if op[i] == last_op:
            opp_run += 1
        else:
            break

    my_run = 1
    for i in range(n - 2, -1, -1):
        if me[i] == last_me:
            my_run += 1
        else:
            break

    dd_run = 0
    if last_me == 'D' and last_op == 'D':
        dd_run = 1
        for i in range(n - 2, -1, -1):
            if me[i] == 'D' and op[i] == 'D':
                dd_run += 1
            else:
                break

    punish = 0
    forgive = 0
    for i in range(n - 1):
        if me[i] == 'D' and op[i] == 'C':
            if op[i + 1] == 'D':
                punish += 1
            elif op[i + 1] == 'C':
                forgive += 1

    if opp_c == 0:
        return 'D'

    if last_op == 'D':
        run_start = n - opp_run
        if run_start > 0 and me[run_start - 1] == 'D' and op[run_start - 1] == 'C':
            if opp_run <= 3 or opp_c * 10 >= n * 7 or rec20_op_c >= 10:
                return 'C'
            return 'D'

        if last_me == 'C':
            if opp_c * 10 >= n * 9 and rec_op_c * 5 >= w * 4 and opp_run <= 2:
                if opp_run == 1:
                    if rng.random() < 0.65:
                        return 'C'
                else:
                    if score_units >= 0 and rng.random() < 0.35:
                        return 'C'
            return 'D'

        if opp_c > 0:
            if rec_op_c >= 1 or dd_run >= 3:
                if rng.random() < 0.45 or dd_run >= 5:
                    return 'C'
        return 'D'

    if last_me == 'D':
        if punish == 0 and forgive >= 2 and rec_op_c >= 7 and rng.random() < 0.8:
            return 'D'
        if n >= 96 and punish == 0 and forgive >= 1 and rng.random() < 0.5:
            return 'D'
        return 'C'

    if n >= 12 and my_c * 5 >= n * 4 and opp_d * 3 >= n and opp_c < n:
        if rng.random() < 0.8:
            return 'D'
        return 'C'

    highly_coop = opp_c * 10 >= n * 9 and rec_op_c * 5 >= w * 4
    if highly_coop and recent_coop20:
        if opp_c == n and my_d > 0:
            return 'D'

        if punish == 0 and forgive > 0:
            p = 0.65
            if n >= 80:
                p = 0.85
            if n >= 92:
                p = 0.95
            if rng.random() < p:
                return 'D'
            return 'C'

        if forgive > punish + 1:
            p = 0.35 + 0.10 * (forgive - punish)
            if n >= 80:
                p += 0.30
            if p > 0.90:
                p = 0.90
            if rng.random() < p:
                return 'D'
            return 'C'

        if punish == 0 and forgive == 0:
            if opp_c == n and my_c == n:
                p = 0.0
                if n >= 90:
                    p = 0.35
                elif n >= 75:
                    p = 0.12
                elif n >= 55:
                    p = 0.03
                if rng.random() < p:
                    return 'D'
            return 'C'

        if n >= 96 and rng.random() < 0.20:
            return 'D'
        return 'C'

    if score_units < 0 and rec_op_c >= 3 and rec_op_d >= 3:
        if rng.random() < 0.60:
            return 'D'
        return 'C'

    return 'C'
